use cssparser::{Delimiter, ParseError, Parser, Token};

const ROOT_SELECTOR: &str = ":root";
const DARK_MEDIA_QUERY: &str = "@media(prefers-color-scheme:dark)";
const CUSTOM_PROPERTY_PREFIX: &str = "--";
const BLOCK_START: char = '{';
const GENERATED_NOTICE: &str =
    "/* Generated by `cargo xtask site-tokens .` from the dark block of tokens.css. Never edited by hand. */";

/// The dark block of a tokens file: every token it declares, in its order, each with the value
/// the file writes.
#[derive(Debug)]
pub(crate) struct DarkTokens {
    declarations: Vec<Declaration>,
}

#[derive(Debug)]
struct Declaration {
    name: String,
    value: String,
}

#[derive(Clone, Copy)]
enum Nesting {
    TopLevel,
    DarkMedia,
}

/// What closes the prelude of a rule.
enum PreludeEnd {
    Block,
    Semicolon,
    EndOfInput,
}

impl DarkTokens {
    /// The dark block of the tokens file with this text; none when the file has no such block.
    /// The compiler of the kit is what holds the file to its shape: this reads the block and
    /// judges nothing else.
    pub(crate) fn of(tokens_text: &str) -> Option<Self> {
        dark_block(&mut Parser::new(tokens_text), Nesting::TopLevel)
    }

    /// A stylesheet that gives a page the dark tokens whatever the color scheme of the system:
    /// one `:root` rule with every declaration of the block.
    pub(crate) fn mirror(&self) -> String {
        let declarations: Vec<String> = self
            .declarations
            .iter()
            .map(|declaration| format!("  {}: {};", declaration.name, declaration.value))
            .collect();
        format!(
            "{GENERATED_NOTICE}\n{ROOT_SELECTOR} {{\n  color-scheme: dark;\n{}\n}}\n",
            declarations.join("\n")
        )
    }
}

fn dark_block(input: &mut Parser<'_>, nesting: Nesting) -> Option<DarkTokens> {
    loop {
        let (prelude, prelude_end) = read_prelude(input);
        match (prelude_end, nesting) {
            (PreludeEnd::EndOfInput, _) => return None,
            (PreludeEnd::Block, Nesting::TopLevel) if is_dark_media_query(prelude) => {
                let dark_tokens = input
                    .parse_nested_block(|media_block| {
                        Ok::<_, ParseError<()>>(dark_block(media_block, Nesting::DarkMedia))
                    })
                    .expect("a media block is read to its end");
                if dark_tokens.is_some() {
                    return dark_tokens;
                }
            }
            (PreludeEnd::Block, Nesting::DarkMedia) if prelude == ROOT_SELECTOR => {
                let declarations = input
                    .parse_nested_block(|tokens_block| Ok::<_, ParseError<()>>(declarations(tokens_block)))
                    .expect("a tokens block is read to its end");
                return Some(DarkTokens { declarations });
            }
            (PreludeEnd::Block | PreludeEnd::Semicolon, _) => {}
        }
    }
}

/// Reads the prelude of the next rule up to what closes it. After a block end the block is
/// open: the caller reads it as a nested block or leaves it to be skipped.
fn read_prelude<'text>(input: &mut Parser<'text>) -> (&'text str, PreludeEnd) {
    input.skip_whitespace();
    let start = input.position();
    loop {
        match input.next().ok().cloned() {
            Some(Token::CurlyBracketBlock) => {
                let prelude = input
                    .slice_from(start)
                    .strip_suffix(BLOCK_START)
                    .expect("a block starts where its token was read");
                return (prelude.trim(), PreludeEnd::Block);
            }
            Some(Token::Semicolon) => return (input.slice_from(start).trim(), PreludeEnd::Semicolon),
            Some(_) => {}
            None => return (input.slice_from(start).trim(), PreludeEnd::EndOfInput),
        }
    }
}

fn is_dark_media_query(prelude: &str) -> bool {
    let without_whitespace: String = prelude.chars().filter(|character| !character.is_whitespace()).collect();
    without_whitespace.eq_ignore_ascii_case(DARK_MEDIA_QUERY)
}

fn declarations(input: &mut Parser<'_>) -> Vec<Declaration> {
    let mut declarations = Vec::new();
    while let Some(token) = input.next().ok().cloned() {
        if let Token::Ident(property) = token
            && property.starts_with(CUSTOM_PROPERTY_PREFIX)
            && input.expect_colon().is_ok()
        {
            declarations.push(Declaration {
                name: property.to_string(),
                value: value_as_written(input),
            });
        }
    }
    declarations
}

/// The value of a declaration up to its `;`, as the file writes it.
fn value_as_written(input: &mut Parser<'_>) -> String {
    input
        .parse_until_before(Delimiter::Semicolon, |value_input| {
            let start = value_input.position();
            while value_input.next().is_ok() {}
            Ok::<_, ParseError<()>>(value_input.slice_from(start).trim().to_owned())
        })
        .expect("a declaration value is read to its end")
}
